print("=== parse_money ===")
assert parse_money('1.005') == Decimal('1.01'), "parse_money(1.005)"
assert parse_money('1.004') == Decimal('1.00'), "parse_money(1.004)"
assert parse_money(2.999) == Decimal('3.00'), "parse_money(2.999)"
assert parse_money('0') == Decimal('0.00'), "parse_money(0)"
assert parse_money('10') == Decimal('10.00'), "parse_money(10)"
try:
    parse_money('-1.00'); print("FAIL: parse_money(-1.00) no raise")
except ValueError as e: print("parse_money(-1.00) ->", e)
try:
    parse_money('abc'); print("FAIL: parse_money(abc) no raise")
except ValueError as e: print("parse_money(abc) ->", e)

