assert apply_discount('1.005', 50) == Decimal('0.50'), "ad(1.005,50)"
assert apply_discount('1.005', 100) == Decimal('0.00'), "ad(1.005,100)"
assert apply_discount('1.005', 33) == Decimal('0.67'), "ad(1.005,33)"
assert apply_discount('1.005', 33.333) == Decimal('0.67'), "ad(1.005,33.333)"
assert apply_discount('10.00', 10) == Decimal('9.00'), "ad(10.00,10)"
assert apply_discount('10.00', 0) == Decimal('10.00'), "ad(10.00,0)"
assert apply_discount('1.005') == Decimal('1.01'), "ad(1.005) default"
try:
    apply_discount('1.00', 101); print("FAIL: ad(1.00,101) no raise")
except ValueError as e: print("ad(1.00,101) ->", e)
try:
    apply_discount('1.00', -1); print("FAIL: ad(1.00,-1) no raise")
except ValueError as e: print("ad(1.00,-1) ->", e)
try:
    apply_discount('-1.00', 0); print("FAIL: ad(-1.00,0) no raise")
except ValueError as e: print("ad(-1.00,0) ->", e)

print("=== line_total ===")
assert line_total('1.005', 3) == Decimal('3.03'), "lt(1.005,3)"
# 1.005*0.5 = 0.5025 -> 0.50; *3 = 1.50
assert line_total('1.005', 3, 50) == Decimal('1.50'), "lt(1.005,3,50)"
assert line_total('1.005', 0) == Decimal('0.00'), "lt(1.005,0)"
assert line_total('1.005', 1) == Decimal('1.01'), "lt(1.005,1)"
for bad_q in [True, False, -1, 2.0, '2']:
    try:
        line_total('1.00', bad_q); print("FAIL: lt(1.00,%r) no raise" % bad_q)
    except ValueError as e: print("lt(1.00,%r) -> %s" % (bad_q, e))
try:
    line_total('-1.00', 1); print("FAIL: lt(-1.00,1) no raise")
except ValueError as e: print("lt(-1.00,1) ->", e)

print("=== pricing.discounted compat ===")
assert discounted('1.005') == Decimal('1.01')
assert discounted('1.005', 50) == Decimal('0.50')
print("discounted OK")

print("=== invoice_total ===")
assert invoice_total([{'price':'1.005','qty':3}]) == Decimal('3.03')
assert invoice_total([{'price':'1.005','qty':3,'discount':50}]) == Decimal('1.50')
assert invoice_total([]) == Decimal('0.00')
assert invoice_total([{'price':'1.00','qty':2},{'price':'2.00','qty':3}]) == Decimal('8.00')
for bad in [{'price':'1.00','qty':-1},{'price':'1.00','qty':True},{'price':'-1.00','qty':1}]:
    try:
        invoice_total([bad]); print("FAIL: invoice_total(%r) no raise" % bad)
    except ValueError as e: print("invoice_total(%r) -> %s" % (bad, e))

print("=== stock_value ===")
assert stock_value([{'price':'2.005','qty':2}]) == Decimal('4.02')
assert stock_value([{'price':'1.00','qty':3}]) == Decimal('3.00')
assert stock_value([]) == Decimal('0.00')
for bad in [{'price':'1.00','qty':-1},{'price':'1.00','qty':True},{'price':'-1.00','qty':1}]:
    try:
        stock_value([bad]); print("FAIL: stock_value(%r) no raise" % bad)
    except ValueError as e: print("stock_value(%r) -> %s" % (bad, e))

print("=== checkout ===")
assert checkout([{'price':'10','qty':2}],2) == {'subtotal':'20.00','shipping':'7.50','total':'27.50'}
assert checkout([{'price':'1.00','qty':1}],0) == {'subtotal':'1.00','shipping':'5.00','total':'6.00'}
assert checkout([{'price':'1.00','qty':1}],0,express=True) == {'subtotal':'1.00','shipping':'10.00','total':'11.00'}
print("checkout OK")
print()
print("ALL CHECKS PASSED")
